def ascii_comment(text):
    """The text for a ; comment: ASCII, everything else as \\uXXXX, control bytes escaped."""
    out = []
    for ch in text:
        code = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif 32 <= code < 127:
            out.append(ch)
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\n":
            out.append("\\n")
        else:
            out.append("\\u%04x" % code)
    return out and "".join(out) or "(empty)"


def arr(name, typ, values):
    assert len(values) >= 2, f"{name}: t27c gen-c cannot write a one-element array"
    return f"pub const {name} : [{len(values)}]{typ} = [{', '.join(map(str, values))}];"


def table(prefix, label, rows, constants):
    """rows: (name, text) -> row index constants, packed bytes, offsets, lengths."""
    text = bytearray()
    offsets, lengths, lines = [], [], []
    for i, (name, value) in enumerate(rows):
        data = value.encode("utf-8")
        offsets.append(len(text))
        lengths.append(len(data))
        text += data
        lines.append(f"; {ascii_comment(value)}")
        lines.append(f"pub const {prefix}_{name} : i64 = {i};")
    if len(text) < 2:
        text += b"\0\0"
    lines.append(f"pub const {prefix}_COUNT : i64 = {len(rows)};")
    lines.append(arr(f"{prefix}_TEXT", "u8", list(text)))
    lines.append(arr(f"{prefix}_OFFSETS", "u32", offsets))
    lines.append(arr(f"{prefix}_LENGTHS", "u32", lengths))
    return [f"; {label}"] + constants + lines


def write_block(spec_name, lines):
    spec = SPECS / spec_name
    source = spec.read_text()
    begin = "; >>> generated by Specs/tables/ponte_tables.py -- edit the lists there, not here"
    block = "\n".join([begin] + lines + ["; <<< generated"])
    pattern = re.escape(begin) + r".*?; <<< generated"
    source, n = re.subn(pattern, lambda _: block, source, flags=re.S)
    if n != 1:
        sys.exit(f"{spec_name}: generated block not found")
    for ch in source:
        if ord(ch) > 127:
            sys.exit(f"{spec_name}: not ASCII after generation")
    if spec.read_text() != source:
        spec.write_text(source)
    return n


def main():
    # device_rules: words, call apps, labels, companions in one table, then the fixtures.
    rows = list(DEVICE_WORDS)
    first_app = len(rows)
    rows += [(f"APP_{i}", app) for i, (app, _) in enumerate(CALL_APPS)]
    first_label = len(rows)
    rows += [(f"LABEL_{i}", label) for i, (_, label) in enumerate(CALL_APPS)]
    first_target = len(rows)
    rows += [(f"COMPANION_TARGET_{i}", t) for i, (t, _) in enumerate(COMPANIONS)]
    first_process = len(rows)
    rows += [(f"COMPANION_PROCESS_{i}", p) for i, (_, p) in enumerate(COMPANIONS)]
    assert [a for a, _ in CALL_APPS] == sorted(a for a, _ in CALL_APPS), "call apps must be sorted by bundle ID"
    constants = [
        f"pub const DV_CALL_APPS : i64 = {len(CALL_APPS)};",
        f"pub const DV_ROW_FIRST_APP : i64 = {first_app};",
        f"pub const DV_ROW_FIRST_LABEL : i64 = {first_label};",
        f"pub const DV_COMPANIONS : i64 = {len(COMPANIONS)};",
        f"pub const DV_ROW_FIRST_COMPANION_TARGET : i64 = {first_target};",
        f"pub const DV_ROW_FIRST_COMPANION_PROCESS : i64 = {first_process};",
    ]
    device = table("DV_ROW", "Rows: words, known call apps and labels (sorted by bundle ID), FaceTime companions",
                   rows, constants)
    device += table("DV_FX", "Texts for the tests", DEVICE_FIXTURES, [])
    write_block("device_rules.t27", device)
    write_block("segment_rules.t27", table("SG_FX", "Texts for the tests", SEGMENT_FIXTURES, []))
    voice_rows = list(VOICE_WORDS)
    first_pt = len(voice_rows)
    voice_rows += [(f"PREFERRED_PT_{i}", n) for i, n in enumerate(PREFERRED_VOICES_PT)]
    first_ru = len(voice_rows)
    voice_rows += [(f"PREFERRED_RU_{i}", n) for i, n in enumerate(PREFERRED_VOICES_RU)]
    voice_constants = [f"pub const VO_ROW_FIRST_PREFERRED_PT : i64 = {first_pt};",
                       f"pub const VO_ROW_FIRST_PREFERRED_RU : i64 = {first_ru};",
                       f"pub const VO_PREFERRED_PT_COUNT : i64 = {len(PREFERRED_VOICES_PT)};",
                       f"pub const VO_PREFERRED_RU_COUNT : i64 = {len(PREFERRED_VOICES_RU)};"]
    voice = table("VO_ROW", "Identifier parts of novelty voices, then the preferred voice names", voice_rows, voice_constants)
    voice += table("VO_FX", "Texts for the tests", VOICE_FIXTURES, [])
    write_block("voice_rules.t27", voice)
    write_block("transcript_rules.t27", table("TR_FX", "Texts for the tests", TRANSCRIPT_FIXTURES, []))
    write_block("context_rules.t27", table("CX_ROW", "Claude effort names by code", CONTEXT_WORDS, []))
    write_block("ui_rules.t27", table("UI_ROW", "Source keys and yes words", UI_WORDS, []))
    print(f"tables: {len(rows)} device rows, {len(DEVICE_FIXTURES) + len(SEGMENT_FIXTURES) + len(VOICE_FIXTURES) + len(TRANSCRIPT_FIXTURES)} fixtures")


if __name__ == "__main__":
    main()
